insert into public.stars (id, profile_id, body, created_at) values
  ('00000000-0000-4000-8000-000000010001', '00000000-0000-4000-8000-000000010000', '가입은 했는데 뭘 써야 할지 몰라서 그냥 오늘 있었던 일.
insert into public.comments (id, star_id, profile_id, parent_id, body, created_at) values
  ('cf227df8-c9ae-4a77-8f02-6ef48306f3a1', '00000000-0000-4000-8000-000000010001', '00000000-0000-4000-8000-000000040000', null, '아 뭔지 알아요 ㅋㅋ 손님 최고', '2026-10-27T00:00:00.000Z'),
  ('6005f390-c74f-4d5b-855b-0c9d1539bc75', '00000000-0000-4000-8000-000000010002', '00000000-0000-4000-8000-000000020000', null, '준비 안 됐으면 굳이 지금 다 설명 안 해도 된대요. 그냥 ''내 거야'' 정도로만 말해도 되고요. 잘 지나가길..', '2026-11-03T00:00:00.000Z'),
  ('5c179ab3-92b4-46b3-8506-84bd4f814765', '00000000-0000-4000-8000-000000010002', '00000000-0000-4000-8000-000000030000', null, '저도 비슷한 일 있었는데 엄마가 끝까지 아무 말 안 하셨어요. 그 침묵이 꼭 나쁜 뜻은 아닐 수도 있어요', '2026-11-04T00:01:00.000Z'),
  ('eb70ebee-e45b-4696-8fba-6fda5811bbb7', '00000000-0000-4000-8000-000000010004', '00000000-0000-4000-8000-000000050000', null, '저는 친구들한테 두 개 다 번갈아 불러달라고 했어요. 한 달쯤 지나니까 한쪽이 더 ''나''같더라고요', '2026-11-14T00:00:00.000Z'),
  ('381802d3-534b-4e63-8419-54679dfb6502', '00000000-0000-4000-8000-000000010004', '00000000-0000-4000-8000-000000080000', null, '소리 예쁜 거 중요함 평생 불릴 거니까', '2026-11-15T00:01:00.000Z'),
  ('c911b9d9-32c1-4f7e-81c6-3f8e59fc9e56', '00000000-0000-4000-8000-000000020001', '00000000-0000-4000-8000-000000060000', null, '확신 없는 사람 진짜 많아요 저도 아직 반반임. 꼭 지금 답을 내야 하는 건 아니라고 생각해요', '2026-10-30T00:00:00.000Z'),
  ('4215aa76-b08e-42c1-85d2-14b54fd35ea3', '00000000-0000-4000-8000-000000020001', '00000000-0000-4000-8000-000000010000', null, '아니라고 생각하면 숨 막힌다는 거 저도 그랬어요', '2026-10-31T00:01:00.000Z'),
  ('ebb0dacf-124c-4eb4-84a6-164dcbd4b88c', '00000000-0000-4000-8000-000000020002', '00000000-0000-4000-8000-000000070000', null, '그 느낌 너무 좋죠 ㅠㅠ 축하해요', '2026-11-08T00:00:00.000Z'),
  ('0d7cd0aa-cf6e-4bcc-8f6d-26b5d9c942e6', '00000000-0000-4000-8000-000000020003', '00000000-0000-4000-8000-000000090000', null, '그 상황에서 웃는 척한 거 잘못 아니에요. 버틴 거예요', '2026-11-17T00:00:00.000Z'),
  ('67450d6b-ea48-42a7-8f5f-6a25ab5dbcb7', '00000000-0000-4000-8000-000000030001', '00000000-0000-4000-8000-000000010000', null, '저도 녹음 듣는 게 제일 힘들어요.. 그래도 일주일 전 거랑 비교하면 조금씩 달라져 있긴 하더라고요', '2026-11-01T00:00:00.000Z'),
  ('f5d69104-1281-4a82-8189-8187cb63ee37', '00000000-0000-4000-8000-000000030003', '00000000-0000-4000-8000-000000020000', null, '와 좋은 친구다 진짜', '2026-11-18T00:00:00.000Z'),
  ('25fa4105-44dd-439c-850b-5a8c64ccb616', '00000000-0000-4000-8000-000000030003', '00000000-0000-4000-8000-000000040000', null, '저도 언젠가 이런 글 쓰고 싶네요 축하해요!!', '2026-11-19T00:01:00.000Z'),
  ('0d2b5571-a7a0-4b08-8959-efe44f3cf3d8', '00000000-0000-4000-8000-000000040001', '00000000-0000-4000-8000-000000070000', null, '졸업하면 진짜 좀 나아져요.. 조금만 버텨요', '2026-10-26T00:00:00.000Z'),
  ('653a1250-b69d-4ee3-8369-3528ed8e986b', '00000000-0000-4000-8000-000000040003', '00000000-0000-4000-8000-000000080000', null, '폰은 다 알고 있음 ㅋㅋㅋ', '2026-11-12T00:00:00.000Z'),
  ('82b60516-370c-4746-85bb-9bc550d0f77c', '00000000-0000-4000-8000-000000050002', '00000000-0000-4000-8000-000000020000', null, '이 글 저장해두고 싶다', '2026-11-09T00:00:00.000Z'),
  ('9d3d5d9c-ee47-44fb-8dd7-827832fa2ea9', '00000000-0000-4000-8000-000000050002', '00000000-0000-4000-8000-000000060000', null, '남들 속도 안 봐도 된다는 말 좋아요', '2026-11-10T00:01:00.000Z'),
  ('57dda8b2-a319-4cfc-84e3-c88e5a202736', '00000000-0000-4000-8000-000000050003', '00000000-0000-4000-8000-000000090000', null, '저 갔던 곳은 미리 말하니까 성으로만 불러주셨어요. 접수할 때 한번 물어봐요!', '2026-11-16T00:00:00.000Z'),
  ('d2f8f747-6e7c-4ca9-8ca0-152cd1c64104', '00000000-0000-4000-8000-000000060001', '00000000-0000-4000-8000-000000030000', null, '가까운 쪽이 없을 수도 있는 건데 그걸 설명해야 하는 게 피곤하죠', '2026-10-29T00:00:00.000Z'),
  ('fb714b00-a06c-487d-80ed-8df722c617f9', '00000000-0000-4000-8000-000000060002', '00000000-0000-4000-8000-000000040000', null, 'ㄹㅇ 두 탭 다 뒤지는 사람 여기요', '2026-11-07T00:00:00.000Z'),
  ('f2135528-37ed-4d15-8fc9-c9ca0e478f10', '00000000-0000-4000-8000-000000070001', '00000000-0000-4000-8000-000000080000', null, '축하해요!! 대신 오래 입지 말고 중간중간 꼭 벗고 쉬어요. 자고 일어나서까지 입으면 몸 상해요', '2026-10-31T00:00:00.000Z'),
  ('168ef4ce-85a9-4d35-8e52-ca1cc5a33d0c', '00000000-0000-4000-8000-000000070001', '00000000-0000-4000-8000-000000070000', 'f2135528-37ed-4d15-8fc9-c9ca0e478f10', '헉 몰랐어요 고마워요', '2026-11-01T00:01:00.000Z'),
  ('dd8cceca-3dc2-4f51-8a73-03066e7b870a', '00000000-0000-4000-8000-000000070003', '00000000-0000-4000-8000-000000020000', null, '아주 짧게 ㅋㅋㅋ 멋져요', '2026-11-19T00:00:00.000Z'),
  ('d9275a0e-6166-4736-85c0-14a7140cde27', '00000000-0000-4000-8000-000000080002', '00000000-0000-4000-8000-000000050000', null, '혼자 알아보지 말고 커뮤니티 상담 창구 같은 데 꼭 물어봐요. 저도 거기서 정리된 자료 받았어요', '2026-11-04T00:00:00.000Z'),
  ('ea346894-944f-4cab-88e5-943ca2cb7d75', '00000000-0000-4000-8000-000000080004', '00000000-0000-4000-8000-000000060000', null, '향에 성별 붙이는 거 이상하다고 늘 생각했어요', '2026-11-18T00:00:00.000Z'),
  ('ab842fdf-2412-4dfc-810e-d12d715330f8', '00000000-0000-4000-8000-000000090002', '00000000-0000-4000-8000-000000010000', null, '와 이거 진짜.. 매번 그 순간만 숨 참게 됨', '2026-11-05T00:00:00.000Z'),
  ('aae3567f-cdda-4c73-8bac-83e84ac84d10', '00000000-0000-4000-8000-000000090002', '00000000-0000-4000-8000-000000060000', null, '그 숫자 왜 아직도 필요한지 모르겠어요', '2026-11-06T00:01:00.000Z'),
  ('96e41fe2-9512-48c5-884a-bbfa3877bd78', '00000000-0000-4000-8000-000000100001', '00000000-0000-4000-8000-000000020000', null, '그 검색기록 지우는 거 저만 한 거 아니었구나', '2026-10-22T00:00:00.000Z'),
  ('2a1b3624-767b-404e-8ccf-3f3f87c53f7e', '00000000-0000-4000-8000-000000100004', '00000000-0000-4000-8000-000000040000', null, '나는 앎 ㅋㅋㅋ 이거 좋다', '2026-11-08T00:00:00.000Z'),
  ('394d12af-6d00-49cf-8446-adaf6ccbac76', '00000000-0000-4000-8000-000000100005', '00000000-0000-4000-8000-000000050000', null, '저도 첫 해엔 멀리서 구경만 했어요. 그것만으로도 충분히 좋았어요', '2026-11-12T00:00:00.000Z'),
  ('d75069b3-2dc0-4300-8968-9ca15933f237', '00000000-0000-4000-8000-000000100006', '00000000-0000-4000-8000-000000030000', null, '전혀 안 이상해요', '2026-11-16T00:00:00.000Z')
